CREATE TABLE "matches" (
  id bigint,
  home varchar,
  away varchar,
  competition text,
  start_time timestamptz,
  game varchar,
  PRIMARY KEY (id)
);



CREATE TABLE "markets" (
  id bigint,
  match_id bigint,
  name varchar,
  market_type varchar,
  PRIMARY KEY (id),
  FOREIGN KEY (match_id) REFERENCES matches(id)
);




CREATE TABLE "selections" (
  id bigint,
  market_id bigint,
  name varchar,
  odds numeric(18,2),
  PRIMARY KEY (id),
  FOREIGN KEY (market_id) REFERENCES markets(id)
);


